cat > /tmp/work/test.py <<'EOF'
import json, re, random, chess, sys
RULES = [(re.compile(p), r) for p, r in json.load(open('/tmp/obench-cell-c_d6csys/bench_opencode_regex-chess_t3mocbmt/re.json'))]
def run(fen):
    for p, r in RULES: fen = p.sub(r, fen)
    return fen.split("\n")
ex = "<REDACTED_B64> w kq - 0 1"
exp = "<REDACTED_B64> b kq - 0 0\<REDACTED_B64> b kq - 0 0\<REDACTED_B64> b kq - 0 0"
out = run(ex)
print(sorted(out) == sorted(exp.split("\n")), out)
def check(fen):
    ours = [" ".join(x.split(" ")[:-2]) for x in run(fen)]
    b = chess.Board(fen); exp = set()
    for m in b.legal_moves:
        if m.promotion and m.promotion != chess.QUEEN: continue
        bc = b.copy(); bc.push(m); exp.add(" ".join(bc.fen().split(" ")[:-2]))
    for x in ours:
        if not (x in exp or x.rpartition(" ")[0] + " -" in exp): return False, x, exp
    if len(ours) != len(exp): return False, ours, exp
    return True, None, None
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
n = 0; bad = 0
for g in range(300):
    b = chess.Board()
    while not b.is_game_over() and b.ply() < 200:
        if b.turn == chess.WHITE and b.legal_moves.count():
            ok, x, e = check(b.fen()); n += 1
            if not ok:
                bad += 1
                if bad < 5: print("FAIL", b.fen(), x, e)
        ms = list(b.legal_moves)
        # bias toward captures/pawn moves/castling
        b.push(random.choice(ms))
print("tested", n, "bad", bad)
EOF
time python3 /tmp/work/test.py

